import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSatkosiaData(){const e=readFileSync(resolve(__dirname,"../../frontend/satkosia-gorge-wetlands-explorer/satkosia-data.js"),"utf-8");return new Function(e+"\nreturn { SATKOSIA_INFO, ECOLOGY_HYDROLOGY, INTERESTING_FACTS, SPECIES_CATALOG, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Satkosia Gorge Wetlands Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadSatkosiaData()}),describe("SATKOSIA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.SATKOSIA_INFO.id).toBe("satkosia-gorge-wetland"),expect(e.SATKOSIA_INFO.name).toContain("Satkosia"),expect(e.SATKOSIA_INFO.ramsarYear).toBe(2022),expect(e.SATKOSIA_INFO.ramsarSiteNo).toBe(2468),expect(e.SATKOSIA_INFO.state).toBe("Odisha")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SATKOSIA_INFO.quickStats)).toBe(!0),expect(e.SATKOSIA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY & INTERESTING_FACTS",()=>{it("contains overview, gorge hydrology, crocodile conservation, and status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.gorgeHydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.crocodileConservation).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()}),it("contains interesting facts array",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(3)})}),describe("SPECIES_CATALOG",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.SPECIES_CATALOG)).toBe(!0),expect(e.SPECIES_CATALOG.length).toBeGreaterThanOrEqual(4)}),it("includes Gharial and Mugger Crocodile",()=>{const t=e.SPECIES_CATALOG.find(e=>"gharial"===e.id),a=e.SPECIES_CATALOG.find(e=>"mugger-crocodile"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"satkosia-gorge-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../satkosia-gorge-wetlands-explorer/index.html")})})});